// Props that reach a reader only as a name: a collapsed inheritance layer lists the names it declares (`members`, an
// interned name list in the canonical JSON) and the component's `props` does not hold them. This sorts those props into
// AMBIENT (what every element has, or a style system: a props table would not lead with them) and API (what a
// dependency's component exposes: its modes, state and composition), by a rule that reads only the layer's type name,
// its file and the prop's name. It describes the default collapse (`dependencies`) of the CLI, the NAPI binding and the
// Vite plugin; the Storybook addon runs at `none` and collapses nothing. It measures; it does not change the resolver.
// Pure apart from `declaredMemberType`, which reads one declaration file.
import { readFileSync } from 'node:fs'
import ts from 'typescript'
import { layerMembers, listedProps } from './canonical.ts'

/** One prop a collapsed layer names and the component does not list. */
export interface LayerOnly {
  /** The component's key in the canonical JSON. */
  key: string
  component: string
  /** The layer's declaring type and file, and how many props it declares. */
  layer: string
  layerFile: string
  layerSize: number
  prop: string
}

export type Kind = 'api' | 'ambient'
/** Which clause of the rule decided: the layer's file, the layer's type, a style system, a global attribute, or, when none
 * of those fits, the prop is a dependency's API. */
export type Why = 'dom file' | 'dom type' | 'style type' | 'global attribute' | 'dependency api'

/** The attributes every element has, which no component's API is about. `defaultValue`, `value`, `type`, `name` and the
 * like are NOT here: they are element-specific, and a dependency's component often uses them as its own API. */
export const GLOBAL_ATTRIBUTES = new Set([
  'className',
  'style',
  'id',
  'title',
  'lang',
  'dir',
  'hidden',
  'tabIndex',
  'role',
  'slot',
  'accessKey',
  'draggable',
  'contentEditable',
  'spellCheck',
  'translate',
  'inputMode',
  'nonce',
])

const DOM_FILE = /\/@types\/react\/|\/@react-types\/shared\/src\/dom\.d\.[cm]?ts$/
const DOM_TYPE =
  /^(GlobalDOMEvents|DOMAttributes|AriaAttributes|AllHTMLAttributes|SVGAttributes|\w*HTMLAttributes|Aria\w*Attributes)$/
const STYLE_TYPE =
  /^(\w*StyleProps?|SystemProps|(Space|Layout|Color|Typography|Border|Flex|Grid|Position|Shadow|Background)Props)$/

/** Every prop a collapsed layer names that the component does not list, once per component and prop. */
export function layerOnly(caliper: any): LayerOnly[] {
  const out: LayerOnly[] = []
  for (const [key, component] of Object.entries<any>(caliper.components)) {
    const listed = listedProps(caliper, component)
    const seen = new Set<string>()
    for (const layer of component.inheritance ?? []) {
      for (const prop of layerMembers(caliper, layer)) {
        if (prop in listed || seen.has(prop)) continue
        seen.add(prop)
        out.push({
          key,
          component: component.displayName,
          layer: layer.typeName,
          layerFile: String(layer.fileName),
          layerSize: layer.totalProps,
          prop,
        })
      }
    }
  }
  return out
}

/** The rule. The first clause that fits decides; a prop none of them fits is API.
 *
 *   1. dom file          the layer's file is `@types/react`, or react-aria's `@react-types/shared/src/dom.d.ts`
 *   2. dom type          the layer's type is a DOM family: `GlobalDOMEvents`, `DOMAttributes`, `AriaAttributes`,
 *                        `AllHTMLAttributes`, `SVGAttributes`, `*HTMLAttributes`, `Aria*Attributes`
 *   3. style type        the layer's type is a style system: `*StyleProps`, `SystemProps`, `Space|Layout|Color|…Props`
 *   4. global attribute  the prop is one every element has (`GLOBAL_ATTRIBUTES`), or starts `aria-` or `data-`
 *   5. dependency api    anything else a collapsed layer names
 */
export function classify(item: Pick<LayerOnly, 'layer' | 'layerFile' | 'prop'>): { kind: Kind; why: Why } {
  if (DOM_FILE.test(item.layerFile)) return { kind: 'ambient', why: 'dom file' }
  if (DOM_TYPE.test(item.layer)) return { kind: 'ambient', why: 'dom type' }
  if (STYLE_TYPE.test(item.layer)) return { kind: 'ambient', why: 'style type' }
  if (GLOBAL_ATTRIBUTES.has(item.prop) || /^(aria|data)-/.test(item.prop))
    return { kind: 'ambient', why: 'global attribute' }
  return { kind: 'api', why: 'dependency api' }
}

/** Why an API prop matters to a reader, by what the prop is called. The first that fits; the rest are `other`. */
export const CATEGORIES: { name: string; match: RegExp; matters: string }[] = [
  {
    name: 'state',
    match:
      /^(value|defaultValue|checked|defaultChecked|open|defaultOpen|visible|selected\w*|expanded\w*|on(Value|Open|Checked|Selected|Expanded)?Change|onClose|onOpen|afterOpenChange)$/,
    matters: 'what the component holds or reports, so what a reader sets to drive it',
  },
  {
    name: 'mode',
    match: /^(mode|type|variant|size|multiple|orientation|collapsible|selectionMode|status|placement|side|align)$/,
    matters: 'chooses the form or behaviour of the component',
  },
  {
    name: 'composition',
    match: /^(asChild|render|as|components|slots|slotProps|container|portal\w*)$/,
    matters: 'changes the element or content the component renders',
  },
  {
    name: 'constraint',
    match: /^(disabled|required|readOnly|name|min|max|step|maxLength|loading|invalid)$/,
    matters: 'validation, disabled or loading state',
  },
  {
    name: 'data',
    match: /^(items|options|data|dataSource|columns|locale|format\w*|filter\w*)$/,
    matters: 'what the component shows',
  },
]
const categoryOf = (prop: string) => CATEGORIES.find((c) => c.match.test(prop))
/** Where a prop's category sits in the order; `other` is last. */
const order = (prop: string) => {
  const index = CATEGORIES.findIndex((c) => c.match.test(prop))
  return index === -1 ? CATEGORIES.length : index
}

/** The type a declaration file writes for `typeName.prop`, as text; `undefined` when it is not a plain member. */
export function declaredMemberType(text: string, typeName: string, prop: string): string | undefined {
  const source = ts.createSourceFile('layer.d.ts', text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS)
  const typed = (members: ts.NodeArray<ts.TypeElement>) => {
    const found = members.find((m) => ts.isPropertySignature(m) && m.name.getText(source) === prop)
    return found && ts.isPropertySignature(found) ? found.type?.getText(source).replaceAll(/\s+/g, ' ') : undefined
// What the layer-only props of one corpus are (src/layer-only.ts), how the collapse threshold sorts them, and what a rule
// by relevance would list that the size rule does not. Pure apart from the `read` it is given.
import { classify, layerOnly, topApi, type Kind, type LayerOnly, type TopApi, type Why } from './layer-only.ts'
import { layerMembers, listedProps } from './canonical.ts'

/** The collapse threshold: a dependency source declaring more props than this is one layer, not a list of props. */
export const THRESHOLD = 30

export interface Input {
  /** The canonical JSON at the default collapse (`dependencies`). */
  caliper: any
  /** The same run with `--collapse-inherited-props none`, for what listing the props would add. */
  expanded?: any
  /** The two JSON documents' sizes in bytes. */
  bytes?: { default: number; expanded: number }
}

const count = (values: string[]) => {
  const out: Record<string, number> = {}
  for (const v of values) out[v] = (out[v] ?? 0) + 1
  return out
}

const bucket = (size: number) => {
  if (size <= THRESHOLD) return `<=${THRESHOLD}`
  if (size <= 40) return '31-40'
  return size <= 60 ? '41-60' : '61+'
}

/** A layer's class by its file and type alone, which is what clauses 1 to 3 read. */
const layerKind = (l: { layer: string; file: string }): Kind =>
  classify({ layer: l.layer, layerFile: l.file, prop: '' }).kind

/** The dependency sources whose props the output lists one by one: each prop records the type that declares it (`parent`),
 * so a source is a distinct type and file, and its size the number of its props listed. Not `@types/react`'s. */
export function expandedDependencySources(caliper: any): { layer: string; file: string; size: number }[] {
  const sources = new Map<string, { layer: string; file: string; names: Set<string> }>()
  for (const prop of Object.values<any>(caliper.props)) {
    const { parent } = prop
    const file = parent ? String(parent.fileName) : ''
    if (!file.includes('/node_modules/') || file.includes('/@types/react/')) continue
    const key = `${parent.name}\u0000${file}`
    const source = sources.get(key) ?? { layer: parent.name, file, names: new Set() }
    source.names.add(prop.name)
    sources.set(key, source)
  }
  return [...sources.values()].map((s) => ({ layer: s.layer, file: s.file, size: s.names.size }))
}

/** The layers of a corpus, once each by type and file: collapsed (they list `members`), expanded dependency sources,
 * and the HTML-element layers React's attributes make. */
export function layerCounts(caliper: any) {
  const layers = new Map<string, { layer: string; file: string; size: number; collapsed: boolean; html: boolean }>()
  for (const component of Object.values<any>(caliper.components)) {
    for (const layer of component.inheritance ?? []) {
      const key = `${layer.typeName}\u0000${layer.fileName}`
      const collapsed = layerMembers(caliper, layer).length > 0
      layers.set(key, {
        layer: layer.typeName,
        file: String(layer.fileName),
        size: layer.totalProps,
        collapsed,
        html: Boolean(layer.htmlElement),
      })
    }
  }
  const all = [...layers.values()]
  const collapsed = all.filter((l) => l.collapsed)
  const expanded = expandedDependencySources(caliper)
  return {
    distinct_layers: all.length,
    html_layers: all.filter((l) => l.html).length,
    collapsed: {
      layers: collapsed.length,
      above_threshold: collapsed.filter((l) => l.size > THRESHOLD).length,
      at_or_below_threshold: collapsed.filter((l) => l.size <= THRESHOLD).length,
      by_size: count(collapsed.map((l) => bucket(l.size))),
      ambient_by_type_or_file: collapsed.filter((l) => layerKind(l) === 'ambient').length,
    },
    expanded_dependency: {
      layers: expanded.length,
      above_threshold: expanded.filter((l) => l.size > THRESHOLD).length,
      at_or_below_threshold: expanded.filter((l) => l.size <= THRESHOLD).length,
      ambient_by_type_or_file: expanded.filter((l) => layerKind(l) === 'ambient').length,
    },
  }
}

/** How many component props a document lists: each component's own and curated inherited ones. */
const listedCount = (caliper: any) =>
  Object.values<any>(caliper.components).reduce((n, c) => n + Object.keys(listedProps(caliper, c)).length, 0)

/** The configuration with nothing collapsed (`--collapse-inherited-props none`), which is the Storybook addon's default
 * (`packages/storybook/src/provider.ts`), next to the default one. Nothing is collapsed there, so no prop is layer-only:
 * what the layer-only measurement describes is the default configuration of the CLI, the NAPI binding and the Vite
 * plugin, and an addon user already has every inherited prop listed. */
function expandedConfig(caliper: any, expanded: any) {
  return {
    collapsed_layers: layerCounts(expanded).collapsed.layers,
    layer_only_props: layerOnly(expanded).length,
    listed_props: { default: listedCount(caliper), expanded: listedCount(expanded) },
  }
}

/** What listing a set of layer-only props would add to the canonical JSON, from the fully expanded run: how many of
 * them it lists, and the bytes of their distinct prop entries plus one `name: id` per component. */
function listing(items: LayerOnly[], expanded: any) {
  const ids = new Set<string>()
  let listed = 0
  let nameBytes = 0
  for (const item of items) {
    const component = expanded.components[item.key]
    const id = component ? listedProps(expanded, component)[item.prop] : undefined
    if (id === undefined) continue
    listed++
    ids.add(id)
    nameBytes += item.prop.length + id.length + 6
  }
  const entryBytes = [...ids].reduce((sum, id) => sum + JSON.stringify(expanded.props[id]).length, 0)
  return { props: listed, distinct_entries: ids.size, bytes_estimate: entryBytes + nameBytes }
}

/** The ambient props a dependency source lists one by one today (the source is small, so the size rule leaves it
 * expanded): how many component props, and the bytes of their distinct entries plus one `name: id` per component. A
 * relevance rule would collapse them. */
export function ambientListedToday(caliper: any) {
  const ids = new Set<string>()
  let props = 0
  let nameBytes = 0
  for (const component of Object.values<any>(caliper.components)) {
    for (const [name, id] of Object.entries(listedProps(caliper, component))) {
      const parent = caliper.props[id]?.parent
      const file = parent ? String(parent.fileName) : ''
      if (!file.includes('/node_modules/') || file.includes('/@types/react/')) continue
      if (classify({ layer: parent.name, layerFile: file, prop: name }).kind !== 'ambient') continue
      props++
      ids.add(id)
      nameBytes += name.length + id.length + 6
    }
  }

